<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Mini Spreadsheet</title>
<style>
  * { box-sizing: border-box; }
  body { margin: 0; padding: 14px; font-family: Arial, sans-serif; background: #fafafa; }
  .app { min-width: 600px; min-height: 400px; }
  .toolbar { margin-bottom: 10px; }
  button#export {
    padding: 7px 14px; font-size: 13px; cursor: pointer;
    border: 1px solid #888; background: #f5f5f5; border-radius: 3px;
  }
  button#export:hover { background: #e8e8e8; }
  .sheet-grid {
    display: grid;
    grid-template-columns: 42px repeat(10, minmax(52px, 1fr));
    grid-template-rows: 28px repeat(10, minmax(30px, 1fr));
    border: 1px solid #999;
    background: #fff;
    width: 100%;
    min-height: 360px;
  }
  .header {
    background: #e8edf2;
    display: flex; align-items: center; justify-content: center;
    border: 1px solid #b9c4d0;
    font-weight: bold; font-size: 13px; color: #333;
    user-select: none;
  }
  .cell {
    width: 100%; height: 100%;
    border: 1px solid #d0d0d0;
    padding: 2px 4px;
    font-size: 13px;
    font-family: monospace;
    background: #fff;
  }
  .cell:focus { outline: 2px solid #3b7dd8; outline-offset: -2px; }
  #csv {
    width: 100%;
    margin-top: 12px;
    font-family: monospace;
    font-size: 12px;
    min-height: 120px;
    padding: 6px;
    box-sizing: border-box;
  }
</style>
</head>
<body>
<div class="app">
  <div class="toolbar">
    <button id="export">Export CSV</button>
  </div>
  <div class="sheet-grid" id="grid"></div>
  <textarea id="csv" placeholder="CSV output will appear here..."></textarea>
</div>
<script>
(function () {
  const COLS = 10;
  const ROWS = 10;
  const allCells = [];
  for (let r = 1; r <= ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const col = String.fromCharCode(65 + c);
      allCells.push(col + r);
    }
  }

  const rawData = {};
  let lastResults = {};
  let editingId = null;

  function isValidCell(ref) {
    const m = ref.match(/^([A-J])([0-9]+)$/);
    if (!m) return false;
    const row = parseInt(m[2], 10);
    return row >= 1 && row <= 10;
  }

  function getDeps(id) {
    const raw = rawData[id] || '';
    if (!raw.startsWith('=')) return [];
    const refs = [];
    const re = /[A-Ja-j][0-9]+/g;
    let m;
    while ((m = re.exec(raw)) !== null) {
      if (m.index >= 1) {
        const ref = m[0].toUpperCase();
        if (isValidCell(ref)) refs.push(ref);
      }
    }
    return refs;
  }

  function inCycle(start) {
    const stack = getDeps(start).slice();
    const seen = new Set();
    while (stack.length) {
      const n = stack.pop();
      if (n === start) return true;
      if (seen.has(n)) continue;
      seen.add(n);
      stack.push.apply(stack, getDeps(n));
    }
    return false;
  }

  function tokenize(s) {
    const tokens = [];
    let i = 0;
    while (i < s.length) {
      const c = s[i];
      if (c === ' ' || c === '\t') { i++; continue; }
      if ('+-*/()'.indexOf(c) >= 0) { tokens.push({ type: 'op', val: c }); i++; continue; }
      if ((c >= '0' && c <= '9') || c === '.') {
        let num = '';
        while (i < s.length && ((s[i] >= '0' && s[i] <= '9') || s[i] === '.')) { num += s[i]; i++; }
        tokens.push({ type: 'num', val: num });
        continue;
      }
      if (/[A-Ja-j]/.test(c)) {
        let ref = '';
        while (i < s.length && /[A-Ja-j0-9]/.test(s[i])) { ref += s[i]; i++; }
        tokens.push({ type: 'ref', val: ref.toUpperCase() });
        continue;
      }
      throw new Error('bad char: ' + c);
    }
    return tokens;
  }

  function evalExpr(expr, compute) {
    const tokens = tokenize(expr);
    let pos = 0;
    function peek() { return tokens[pos]; }
    function parseExpr() {
      let left = parseTerm();
      while (peek() && (peek().val === '+' || peek().val === '-')) {
        const op = peek().val; pos++;
        const right = parseTerm();
        left = op === '+' ? left + right : left - right;
      }
      return left;
    }
    function parseTerm() {
      let left = parseFactor();
      while (peek() && (peek().val === '*' || peek().val === '/')) {
        const op = peek().val; pos++;
        const right = parseFactor();
        left = op === '*' ? left * right : left / right;
      }
      return left;
    }
    function parseFactor() {
      const t = peek();
      if (!t) throw new Error('unexpected end');
      if (t.val === '-' || t.val === '+') {
        pos++;
        const f = parseFactor();
        return t.val === '-' ? -f : f;
      }
      if (t.val === '(') {
        pos++;
        const e = parseExpr();
        const close = peek();
        if (!close || close.val !== ')') throw new Error('expected )');
        pos++;
        return e;
      }
      if (t.type === 'num') { pos++; return Number(t.val); }
      if (t.type === 'ref') {
        pos++;
        if (!isValidCell(t.val)) throw new Error('bad ref');
        const r = compute(t.val);
        if (r.error || r.cycle || r.text) throw new Error('bad ref value');
        return r.value;
      }
      throw new Error('unexpected token');
    }
    const result = parseExpr();
    if (pos < tokens.length) throw new Error('trailing tokens');
    return result;
  }

  function formatNum(n) {
    if (!isFinite(n)) return '#ERR';
    const rounded = Math.round(n * 1e10) / 1e10;
    return String(rounded);
  }

  function computeAll() {
    const cycleCells = new Set();
    for (const id of allCells) {
      if (inCycle(id)) cycleCells.add(id);
    }

    const memo = {};
    function compute(id) {
      if (memo[id]) return memo[id];
      if (cycleCells.has(id)) {
        memo[id] = { display: '#CYCLE', cycle: true };
        return memo[id];
      }
      const raw = rawData[id] || '';
      if (!raw.startsWith('=')) {
        let result;
        if (raw === '') {
          result = { value: 0, display: '' };
        } else {
          const n = Number(raw);
          if (!isNaN(n) && raw.trim() !== '') {
            result = { value: n, display: formatNum(n) };
          } else {
            result = { display: raw, text: true };
          }
        }
        memo[id] = result;
        return result;
      }
      try {
        const val = evalExpr(raw.slice(1), compute);
        if (!isFinite(val)) {
          memo[id] = { display: '#ERR', error: true };
        } else {
          memo[id] = { value: val, display: formatNum(val) };
        }
        return memo[id];
      } catch (e) {
        memo[id] = { display: '#ERR', error: true };
        return memo[id];
      }
    }

    for (const id of allCells) compute(id);
    return memo;
  }

  function recalc() {
    lastResults = computeAll();
    for (const id of allCells) {
      if (id === editingId) continue;
      const input = document.getElementById('cell-' + id);
      if (input) input.value = lastResults[id].display;
    }
  }

  // Build the grid
  const grid = document.getElementById('grid');
  const corner = document.createElement('div');
  corner.className = 'header';
  grid.appendChild(corner);
  for (let c = 0; c < COLS; c++) {
    const h = document.createElement('div');
    h.className = 'header';
    h.textContent = String.fromCharCode(65 + c);
    grid.appendChild(h);
  }
  for (let r = 1; r <= ROWS; r++) {
    const rh = document.createElement('div');
    rh.className = 'header';
    rh.textContent = r;
    grid.appendChild(rh);
    for (let c = 0; c < COLS; c++) {
      const col = String.fromCharCode(65 + c);
      const id = col + r;
      const input = document.createElement('input');
      input.type = 'text';
      input.id = 'cell-' + id;
      input.className = 'cell';
      input.value = '';
      input.addEventListener('focus', function () {
        editingId = id;
        input.value = rawData[id] || '';
      });
      input.addEventListener('blur', function () {
        rawData[id] = input.value;
        editingId = null;
        recalc();
      });
      input.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') {
          e.preventDefault();
          input.blur();
        }
      });
      grid.appendChild(input);
    }
  }

  recalc();

  // Export CSV
  document.getElementById('export').addEventListener('click', function () {
    const lines = [];
    for (let r = 1; r <= ROWS; r++) {
      const cols = [];
      for (let c = 0; c < COLS; c++) {
        const col = String.fromCharCode(65 + c);
        const id = col + r;
        const val = lastResults[id] ? lastResults[id].display : '';
        if (/[",\n]/.test(val)) {
          cols.push('"' + val.replace(/"/g, '""') + '"');
        } else {
          cols.push(val);
        }
      }
      lines.push(cols.join(','));
    }
    document.getElementById('csv').value = lines.join('\n');
  });

  // Scripting API
  window.sheet = {
    set: function (id, text) {
      rawData[id] = text;
      recalc();
    },
    get: function (id) {
      const input = document.getElementById('cell-' + id);
      return input ? input.value : '';
    },
    raw: function (id) {
      return rawData[id] || '';
    }
  };
})();
</script>
</body>
</html>
